import { MongoAbility, AbilityBuilder } from '@casl/ability';

type Actions = 'create' | 'update' | 'delete' | 'pause';
type Subjects = 'Article' | 'Transfers' | 'all';
export type AppAbility = MongoAbility<[Actions, Subjects]>;

export function defineAbility(user: User): AppAbility {
  const { can, cannot, build } = new AbilityBuilder<AppAbility>(MongoAbility);
  if (user.roles.includes('pauser')) can('pause', 'Transfers');
  if (user.roles.includes('editor')) can('update', 'Article', { authorId: user.id });
  cannot('delete', 'Article');
  return build();
}

@Injectable()
export class PermissionsGuard implements CanActivate {          // registered as APP_GUARD
  constructor(private reflector: Reflector, private casl: CaslAbilityFactory) {}
  canActivate(ctx: ExecutionContext): boolean {
    const required = this.reflector.getAllAndOverride<Permission[]>(PERMISSIONS_KEY,
      [ctx.getHandler(), ctx.getClass()]);
    if (!required) return false;                                // deny by default
    const { user } = ctx.switchToHttp().getRequest();
    const ability = this.casl.createForUser(user);
    return required.every((p) => ability.can(p.action, p.subject));
  }
}
